def _compute_provenance(
    domain: str,
    task_id: Optional[str],
    model: Optional[str],
) -> Dict[str, str]:
    """Trace which layer set each parameter in the effective policy.

    Builds the policy layer by layer and records when each dotpath
    first appears or changes value.
    """
    provenance: Dict[str, str] = {}
    current: Dict[str, Any] = {}

    # Layer 1: Universal
    universal_path = REGISTRY_DIR / "universal.toml"
    if not universal_path.exists():
        return provenance
    universal_config = _load_toml(universal_path)
    for dp, val in _flatten_dict(universal_config).items():
        provenance[dp] = "universal"
    current = _deep_merge(current, universal_config)

    # Helper to update provenance when values change
    def _update_provenance(new_config: Dict[str, Any], layer: str) -> None:
        nonlocal current
        new_current = _deep_merge(current, new_config)
        flat_new = _flatten_dict(new_current)
        flat_old = _flatten_dict(current)
        for dp, val in flat_new.items():
            if dp not in flat_old or flat_old[dp] != val:
                provenance[dp] = layer
        current = new_current

    # Layer 2: Domain
    domain_key = DOMAIN_MAP.get(domain)
    if domain_key:
        domain_path = REGISTRY_DIR / "domains" / f"{domain_key}.toml"
        if domain_path.exists():
            _update_provenance(_load_toml(domain_path), f"domain/{domain_key}")

    # Layer 3: Task
    if task_id:
        task_path = REGISTRY_DIR / "tasks" / f"{task_id}.toml"
        if task_path.exists():
            _update_provenance(_load_toml(task_path), f"task/{task_id}")

    # Layer 4: Model
    if model:
        model_path = REGISTRY_DIR / "models" / f"{model}.toml"
        if model_path.exists():
            _update_provenance(_load_toml(model_path), f"model/{model}")

    return provenance
